import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();
        int n = sc.nextInt();
        long num, den;

        if (n >= y) {
            int g = gcd(x, y);
            num = x / g;
            den = y / g;
        } else {
            double best_diff = 1e15;
            num = 0;
            den = 1;
            for (int i = 1; i <= n; ++i) {
                double ratio = (double) x / y;
                double candidate_floor = Math.floor((double) x * i / y);
                if (Math.abs(candidate_floor / i - ratio) < best_diff) {
                    num = (long) candidate_floor;
                    den = i;
                    best_diff = Math.abs(candidate_floor / i - ratio);
                }
                double candidate_ceil = Math.ceil((double) x * i / y);
                if (Math.abs(candidate_ceil / i - ratio) < best_diff) {
                    num = (long) candidate_ceil;
                    den = i;
                    best_diff = Math.abs(candidate_ceil / i - ratio);
                }
            }
        }
        System.out.println(num + "/" + den);
        sc.close();
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
